// CE allele frequencies (Illumina ForenSeq) sourced from pop.STR JSON exports in TEMP-strpop/.
// Counts are not provided by pop.STR JSON; set to 0.

export type CEPop = "AFR" | "NAM" | "EAS" | "CSA" | "EUR" | "MES" | "OCE";
export type NGSPop = "AFR" | "AMR" | "EUR" | "EAS" | "SAS" | "RAO";
export type Pop = CEPop | NGSPop;
export type AlleleEntry = { allele: string; frequency: number; count: number };

/** NGS frequency blocks: `kit` is optional when data are not tied to a single commercial kit. */
export type MarkerFrequencyNGSEntry = {
  kit?: string
  technology: string
} & Partial<Record<NGSPop, AlleleEntry[]>>

